-- Create "complaint_settings" table
CREATE TABLE "complaint_settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "comments" boolean NOT NULL DEFAULT true, "node_types" jsonb NULL, "reasons" text NULL, "hide_after" bigint NOT NULL DEFAULT 3, PRIMARY KEY ("id"));
-- Create "complaint_targets" table
CREATE TABLE "complaint_targets" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "kind" character varying NOT NULL, "object_id" bigint NOT NULL, "node_id" bigint NOT NULL, "author_id" bigint NOT NULL DEFAULT 0, "status" character varying NOT NULL DEFAULT 'new', "hidden" boolean NOT NULL DEFAULT false, "resolution" character varying NOT NULL DEFAULT '', "resolved_by" bigint NOT NULL DEFAULT 0, "resolved_at" timestamptz NULL, "last_at" timestamptz NOT NULL, "created_at" timestamptz NOT NULL, PRIMARY KEY ("id"));
-- Create index "uniq_complaint_targets_kind_object" to table: "complaint_targets"
CREATE UNIQUE INDEX "uniq_complaint_targets_kind_object" ON "complaint_targets" ("kind", "object_id");
-- Create index "idx_complaint_targets_status_last" to table: "complaint_targets"
CREATE INDEX "idx_complaint_targets_status_last" ON "complaint_targets" ("status", "last_at");
-- Create index "idx_complaint_targets_node" to table: "complaint_targets"
CREATE INDEX "idx_complaint_targets_node" ON "complaint_targets" ("node_id");
-- Create "complaints" table
CREATE TABLE "complaints" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "user_id" bigint NOT NULL, "reason" character varying NOT NULL, "comment" character varying NOT NULL DEFAULT '', "created_at" timestamptz NOT NULL, "target_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "complaints_complaint_targets_complaints" FOREIGN KEY ("target_id") REFERENCES "complaint_targets" ("id") ON DELETE CASCADE);
-- Create index "uniq_complaints_target_user" to table: "complaints"
CREATE UNIQUE INDEX "uniq_complaints_target_user" ON "complaints" ("target_id", "user_id");
-- Create index "idx_complaints_user" to table: "complaints"
CREATE INDEX "idx_complaints_user" ON "complaints" ("user_id");
